template:
ip access-list permithosts
  permit tcp 192.168.10.0/24 {{1}}
  permit tcp 192.168.10.0/24 host 192.168.20.1 eq 3389
  permit icmp 192.168.10.0/24 host 192.168.20.1

class-map type control-plane match-any hostscmap
  match {{2}}

policy-map type control-plane hostspmap
  {{3}}
  police cir 54000 pps bc 128 packets {{4}}
